Here's a comprehensive guide on how to use the Vicuna language model in SwiftUI:

## Option 1: Using Ollama (Recommended for Local Development)

First, install Ollama and pull the Vicuna model:

```bash
# Install Ollama
curl -fsSL https://ollama.ai/install.sh | sh

# Pull Vicuna model
ollama pull vicuna
```

### SwiftUI Implementation with Ollama

```swift
import SwiftUI
import Foundation

// MARK: - Data Models
struct OllamaRequest: Codable {
    let model: String
    let prompt: String
    let stream: Bool = false
}

struct OllamaResponse: Codable {
    let response: String
}

// MARK: - Ollama Service
class OllamaService: ObservableObject {
    @Published var response: String = ""
    @Published var isLoading: Bool = false
    @Published var error: String?

    private let baseURL = "http://localhost:11434"

    func generateResponse(prompt: String) async {
        await MainActor.run {
            isLoading = true
            error = nil
            response = ""
        }

        guard let url = URL(string: "\(baseURL)/api/generate") else {
            await MainActor.run {
                error = "Invalid URL"
                isLoading = false
            }
            return
        }

        let request = OllamaRequest(model: "vicuna", prompt: prompt)

        do {
            var urlRequest = URLRequest(url: url)
            urlRequest.httpMethod = "POST"
            urlRequest.setValue("application/json", forHTTPHeaderField: "Content-Type")
            urlRequest.httpBody = try JSONEncoder().encode(request)

            let (data, _) = try await URLSession.shared.data(for: urlRequest)
            let ollamaResponse = try JSONDecoder().decode(OllamaResponse.self, from: data)

            await MainActor.run {
                self.response = ollamaResponse.response
                self.isLoading = false
            }
        } catch {
            await MainActor.run {
                self.error = error.localizedDescription
                self.isLoading = false
            }
        }
    }
}

// MARK: - SwiftUI Views
struct VicunaView: SwiftUI.View {
    @StateObject private var ollamaService = OllamaService()
    @State private var inputText = ""

    var body: some SwiftUI.View {
        NavigationView {
            VStack(spacing: 20) {
                // Input Section
                VStack(alignment: .leading, spacing: 10) {
                    Text("Enter your prompt:")
                        .font(.headline)

                    TextEditor(text: $inputText)
                        .frame(minHeight: 100)
                        .padding(8)
                        .background(Color.gray.opacity(0.1))
                        .cornerRadius(8)
                }

                // Send Button
                Button(action: {
                    Task {
                        await ollamaService.generateResponse(prompt: inputText)
                    }
                }) {
                    HStack {
                        if ollamaService.isLoading {
                            ProgressView()
                                .scaleEffect(0.8)
                        }
                        Text(ollamaService.isLoading ? "Generating..." : "Generate Response")
                    }
                    .frame(maxWidth: .infinity)
                    .padding()
                    .background(inputText.isEmpty ? Color.gray : Color.blue)
                    .foregroundColor(.white)
                    .cornerRadius(8)
                }
                .disabled(inputText.isEmpty || ollamaService.isLoading)

                // Response Section
                VStack(alignment: .leading, spacing: 10) {
                    Text("Vicuna Response:")
                        .font(.headline)

                    ScrollView {
                        Text(ollamaService.response.isEmpty ? "No response yet" : ollamaService.response)
                            .frame(maxWidth: .infinity, alignment: .leading)
                            .padding()
                            .background(Color.gray.opacity(0.05))
                            .cornerRadius(8)
                    }
                    .frame(maxHeight: 300)
                }

                // Error Display
                if let error = ollamaService.error {
                    Text("Error: \(error)")
                        .foregroundColor(.red)
                        .padding()
                        .background(Color.red.opacity(0.1))
                        .cornerRadius(8)
                }

                Spacer()
            }
            .padding()
            .navigationTitle("Vicuna Chat")
        }
    }
}
```

## Option 2: Chat Interface with Message History

```swift
import SwiftUI
import Foundation

// MARK: - Chat Models
struct ChatMessage: Identifiable, Codable {
    let id = UUID()
    let content: String
    let isUser: Bool
    let timestamp: Date
}

class VicunaChatViewModel: ObservableObject {
    @Published var messages: [ChatMessage] = []
    @Published var currentMessage = ""
    @Published var isLoading = false

    private let ollamaService = OllamaService()

    func sendMessage() {
        guard !currentMessage.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }

        // Add user message
        let userMessage = ChatMessage(content: currentMessage, isUser: true, timestamp: Date())
        messages.append(userMessage)

        let prompt = currentMessage
        currentMessage = ""
        isLoading = true

        Task {
            await ollamaService.generateResponse(prompt: prompt)

            await MainActor.run {
                // Add Vicuna's response
                let response = ollamaService.response.isEmpty ? "Sorry, I couldn't generate a response." : ollamaService.response
                let botMessage = ChatMessage(content: response, isUser: false, timestamp: Date())
                self.messages.append(botMessage)
                self.isLoading = false
            }
        }
    }
}

struct VicunaChatView: SwiftUI.View {
    @StateObject private var viewModel = VicunaChatViewModel()

    var body: some SwiftUI.View {
        VStack {
            // Messages List
            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(spacing: 12) {
                        ForEach(viewModel.messages) { message in
                            ChatBubbleView(message: message)
                        }

                        if viewModel.isLoading {
                            HStack {
                                ProgressView()
                                Text("Vicuna is thinking...")
                                    .foregroundColor(.gray)
                            }
                            .padding()
                        }
                    }
                    .padding()
                }
                .onChange(of: viewModel.messages.count) { _ in
                    if let lastMessage = viewModel.messages.last {
                        withAnimation {
                            proxy.scrollTo(lastMessage.id, anchor: .bottom)
                        }
                    }
                }
            }

            // Input Area
            HStack {
                TextField("Type your message...", text: $viewModel.currentMessage, axis: .vertical)
                    .textFieldStyle(RoundedBorderTextFieldStyle())
                    .onSubmit {
                        viewModel.sendMessage()
                    }

                Button(action: viewModel.sendMessage) {
                    Image(systemName: "paperplane.fill")
                        .foregroundColor(.white)
                        .padding(8)
                        .background(viewModel.currentMessage.isEmpty ? Color.gray : Color.blue)
                        .clipShape(Circle())
                }
                .disabled(viewModel.currentMessage.isEmpty || viewModel.isLoading)
            }
            .padding()
        }
        .navigationTitle("Vicuna Chat")
    }
}

struct ChatBubbleView: SwiftUI.View {
    let message: ChatMessage

    var body: some SwiftUI.View {
        HStack {
            if message.isUser {
                Spacer()
                VStack(alignment: .trailing) {
                    Text(message.content)
                        .padding()
                        .background(Color.blue)
                        .foregroundColor(.white)
                        .clipShape(RoundedRectangle(cornerRadius: 16))

                    Text(message.timestamp, style: .time)
                        .font(.caption2)
                        .foregroundColor(.gray)
                }
            } else {
                VStack(alignment: .leading) {
                    HStack {
                        Image(systemName: "brain.head.profile")
                            .foregroundColor(.purple)
                        Text("Vicuna")
                            .font(.caption)
                            .foregroundColor(.purple)
                        Spacer()
                    }

                    Text(message.content)
                        .padding()
                        .background(Color.gray.opacity(0.2))
                        .clipShape(RoundedRectangle(cornerRadius: 16))

                    Text(message.timestamp, style: .time)
                        .font(.caption2)
                        .foregroundColor(.gray)
                }
                Spacer()
            }
        }
    }
}
```

